# ==============================================================================# 075_CAPABILITY_ACQUISITION_ENGINE.py## IOTEC CAPABILITY ACQUISITION ENGINE## Missão:# Descobrir automaticamente quais capacidades faltam para que# os agentes consigam executar suas missões.## NÃO instala nada.# NÃO altera o sistema.# Apenas identifica, classifica e recomenda.## ==============================================================================from __future__ import annotationsimport sqlite3import jsonimport hashlibimport socketfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CapabilityAcquisitionEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS capability_requests(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            request_id TEXT,            agent TEXT,            mission TEXT,            capability TEXT,            justification TEXT,            impact TEXT,            urgency TEXT,            suggested_solution TEXT,            status TEXT,            metadata TEXT,            hostname TEXT,            hash TEXT        )        """)        self.conn.commit()    # ----------------------------------------------------------------------    def _hash(self,data):        raw=json.dumps(data,sort_keys=True,ensure_ascii=False)        return hashlib.sha256(raw.encode()).hexdigest()    # ----------------------------------------------------------------------    def request(        self,        agent,        mission,        capability,        justification,        impact,        urgency="MEDIA",        suggested_solution="",        metadata=None    ):        metadata=metadata or {}        timestamp=datetime.utcnow().isoformat()        request_id=hashlib.md5(            f"{timestamp}{agent}{capability}".encode()        ).hexdigest()        payload={            "timestamp":timestamp,            "request_id":request_id,            "agent":agent,            "mission":mission,            "capability":capability,            "justification":justification,            "impact":impact,            "urgency":urgency,            "suggested_solution":suggested_solution,            "status":"PENDING",            "metadata":metadata,            "hostname":socket.gethostname()        }        assinatura=self._hash(payload)        self.conn.execute("""        INSERT INTO capability_requests(            timestamp,            request_id,            agent,            mission,            capability,            justification,            impact,            urgency,            suggested_solution,            status,            metadata,            hostname,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["request_id"],            payload["agent"],            payload["mission"],            payload["capability"],            payload["justification"],            payload["impact"],            payload["urgency"],            payload["suggested_solution"],            payload["status"],            json.dumps(payload["metadata"],ensure_ascii=False),            payload["hostname"],            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=CapabilityAcquisitionEngine()    req=engine.request(        agent="LEAD_AGENT_001",        mission="Captar empresas do setor industrial",        capability="BASE_EMPRESARIAL",        justification="Não existe capacidade para localizar empresas industriais em escala.",        impact="Sem esta capacidade a missão fica limitada.",        urgency="ALTA",        suggested_solution="Pesquisar tecnologias, APIs ou bases empresariais compatíveis.",        metadata={            "segmento":"Industrial",            "pais":"Brasil"        }    )    print("="*80)    print("CAPABILITY REQUEST")    print("="*80)    for k,v in req.items():        print(f"{k:22}: {v}")    print("="*80)